SELECT day::text AS day, upload::text AS upload, download::text AS download,
       upload_ack::text AS "uploadAck", download_ack::text AS "downloadAck",
       loss::text AS loss, loss_ratio::text AS "lossRatio",
       seeding::text AS seeding, downloading::text AS downloading
FROM user_traffic_daily WHERE user_id = #{uid}
ORDER BY day DESC LIMIT #{size} OFFSET #{offset}

SELECT day, upload, download, upload_ack, download_ack, seeding, downloading, loss, loss_ratio
FROM user_traffic_daily WHERE user_id = #{uid}
ORDER BY day DESC LIMIT #{limit}
